-- ETL / backfill / data-quality patterns
INSERT INTO events SELECT * FROM events_old WHERE ts >= '2024-01-01' AND ts < '2024-02-01';
INSERT INTO daily_agg SELECT toDate(ts) AS day, key, uniqState(user_id), quantileState(0.9)(v) FROM events GROUP BY day, key;
INSERT INTO t (a, b) SETTINGS async_insert = 1, wait_for_async_insert = 0 VALUES (1, 'x');
INSERT INTO FUNCTION s3('https://bucket.s3.amazonaws.com/out.parquet', 'Parquet') SELECT * FROM events;
INSERT INTO t SELECT * FROM file('in.csv', 'CSVWithNames');
INSERT INTO t SELECT * FROM url('https://example.com/x.json', 'JSONEachRow');
INSERT INTO t SELECT number, toString(number) FROM numbers(1000000);
SELECT count(), uniqExact(id), count() - uniqExact(id) AS dupes FROM events;
SELECT id, count() AS c FROM events GROUP BY id HAVING c > 1 ORDER BY c DESC LIMIT 100;
SELECT countIf(x IS NULL) AS null_cnt, countIf(x = '') AS empties, count() AS total FROM t;
SELECT min(ts), max(ts), dateDiff('hour', min(ts), max(ts)) FROM events;
SELECT partition, count() FROM system.parts WHERE table = 'events' AND active GROUP BY partition ORDER BY partition;
SELECT toDate(ts) AS d, count() FROM events GROUP BY d HAVING count() < 100 ORDER BY d;
SELECT * FROM events WHERE ts >= '2024-01-01 00:00:00' AND ts < '2024-01-02 00:00:00' AND NOT (user_id = 0 OR name = '');
SELECT a.id FROM src AS a LEFT ANTI JOIN dst AS b ON a.id = b.id;
SELECT id FROM src WHERE id NOT IN (SELECT id FROM dst);
SELECT s.id, s.v FROM src AS s ANY LEFT JOIN dst AS d ON s.id = d.id WHERE d.id = 0;
SELECT arrayJoin(range(0, 10)) AS i;
SELECT ts, value, runningDifference(value) AS delta FROM (SELECT ts, value FROM metrics ORDER BY ts);
SELECT neighbor(value, -1) AS prev, value FROM metrics;
SELECT id, any(name), anyLast(name), min(ts), max(ts) FROM events GROUP BY id;
SELECT id, argMax(name, version) FROM users_rmt GROUP BY id;
SELECT tuple(a, b) AS pair, (a, b) AS pair2, tupleElement(pair, 1) FROM t;
SELECT t.1, t.2 FROM (SELECT (1, 'a') AS t);
SELECT toString(now(), 'UTC'), toUnixTimestamp(now()), fromUnixTimestamp(1700000000), toDate32('1990-01-01');
SELECT count() FROM events WHERE has(tags, 'x') AND length(tags) > 2 AND arrayExists(t -> t = 'y', tags);
SELECT if(isNull(x), 0, x) + 1 FROM t;
SELECT a > 1 ? 'big' : 'small' FROM t;
SELECT intDiv(toUInt32(ts), 300) * 300 AS bucket, count() FROM events GROUP BY bucket;
SELECT lower(hex(MD5(concat(a, '|', b)))) AS k FROM t;
SELECT (SELECT count() FROM events) AS total, (SELECT max(ts) FROM events) AS latest;
SELECT e.id FROM events e WHERE EXISTS (SELECT 1 FROM users u WHERE u.id = e.user_id);
SELECT * FROM events WHERE user_id IN (SELECT id FROM users WHERE country IN ('US', 'CA')) AND ts > now() - INTERVAL 7 DAY ORDER BY ts DESC LIMIT 1000;
SELECT * FROM events e INNER JOIN (SELECT user_id, max(ts) AS ts FROM events GROUP BY user_id) m ON e.user_id = m.user_id AND e.ts = m.ts;
ALTER TABLE events REPLACE PARTITION '202401' FROM events_staging;
ALTER TABLE events MOVE PARTITION '202401' TO TABLE events_archive;
ALTER TABLE events UPDATE name = 'x' IN PARTITION '202401' WHERE id = 1;
ALTER TABLE events DELETE IN PARTITION '202401' WHERE ts < '2024-01-05';
ALTER TABLE events CLEAR COLUMN legacy IN PARTITION '202401';
OPTIMIZE TABLE events_staging FINAL;
